using FluentValidation;
using Kalypsis.Application.Features.Claims;
using Kalypsis.Application.Features.ClaimInvolvedParties;
using Kalypsis.Domain.Entities;
using Kalypsis.Domain.Enums;
using Microsoft.EntityFrameworkCore;
using Xunit;
namespace Kalypsis.Tests;
public class ClaimCardParityTests
{
 internal static async Task<Claim> Seed(Kalypsis.Infrastructure.Persistence.AppDbContext db,Guid tenant,string number){var policy=new Policy{Id=Guid.NewGuid(),TenantId=tenant,PolicyNumber=number,Customer=new(){Id=Guid.NewGuid(),TenantId=tenant,CustomerNumber=number},InsuranceCompany=new(){Id=Guid.NewGuid(),TenantId=tenant,Code=number,Name=number},Currency="EUR",StartDate=new(2026,1,1),EndDate=new(2027,1,1)};policy.CustomerId=policy.Customer.Id;policy.InsuranceCompanyId=policy.InsuranceCompany.Id;var claim=new Claim{Id=Guid.NewGuid(),TenantId=tenant,ClaimNumber=number,Policy=policy,PolicyId=policy.Id,IncidentDate=new(2026,1,2),ReportedDate=new(2026,1,3),SettledAmount=150,ApprovedAmount=800,UsaeCode="KEEP",LiabilityPercent=50};db.Claims.Add(claim);await db.SaveChangesAsync();return claim;}
 [Fact] public async Task Complete_card_saves_status_and_fields_atomically_and_legacy_updates_preserve_additional_values(){var user=TestScaffold.AgencyStaff(Guid.NewGuid());await using var db=TestScaffold.NewDb(user,TestScaffold.Clock);var claim=await Seed(db,user.TenantId!.Value,"CL1");var handler=new UpdateClaimCommandHandler(db,user);var body=new UpdateClaimBody(new(2026,1,2),new(2026,1,3),1200,950.25m,"Details",ClaimNumber:"CL2",Status:ClaimStatus.Pending,Kind:"Fire",SettledAmount:125,Currency:"EUR",AffectsBonusMalus:false,UsaeCode:"U1",UsaeKind:"Υλικά",UsaeStatus:"Accepted",LiabilityPercent:25.5m,IsInternalDamage:true,UsaeSentAt:TestScaffold.Clock.UtcNow,UsaeReceiptCode:"R1",IsFriendlySettlement:true,ReplaceAdditional:true);new UpdateClaimCommandValidator().ValidateAndThrow(new(claim.Id,body));var dto=await handler.Handle(new(claim.Id,body),default);Assert.Equal("CL2",dto.ClaimNumber);Assert.Equal(ClaimStatus.Pending,dto.Status);Assert.Equal(950.25m,dto.ApprovedAmount);Assert.Equal(125,dto.SettledAmount);Assert.False(dto.AffectsBonusMalus);Assert.Equal(25.5m,dto.LiabilityPercent);Assert.True(dto.IsFriendlySettlement);
 var old=await handler.Handle(new(claim.Id,new(new(2026,1,2),new(2026,1,3),1000,800,"Old client")),default);Assert.Equal("U1",old.UsaeCode);Assert.Equal(125,old.SettledAmount);
 var cleared=await handler.Handle(new(claim.Id,body with{UsaeCode=null,LiabilityPercent=null,UsaeSentAt=null,SettledAmount=null}),default);Assert.Null(cleared.UsaeCode);Assert.Null(cleared.LiabilityPercent);Assert.Null(cleared.SettledAmount);
 }
 [Theory][InlineData(-1,0)][InlineData(0,101)] public void Negative_money_and_invalid_liability_are_rejected(decimal paid,decimal liability){var body=new UpdateClaimBody(new(2026,1,1),new(2026,1,2),0,0,null,SettledAmount:paid,LiabilityPercent:liability);Assert.False(new UpdateClaimCommandValidator().Validate(new UpdateClaimCommand(Guid.NewGuid(),body)).IsValid);}
 [Fact] public async Task Tenant_boundaries_and_duplicate_claim_numbers_are_enforced(){var user=TestScaffold.AgencyStaff(Guid.NewGuid());await using var db=TestScaffold.NewDb(user,TestScaffold.Clock);var first=await Seed(db,user.TenantId!.Value,"CL1");await Seed(db,user.TenantId.Value,"CL2");var body=new UpdateClaimBody(first.IncidentDate,first.ReportedDate,0,0,null,ClaimNumber:"CL2");await Assert.ThrowsAsync<Kalypsis.Application.Common.AppException>(()=>new UpdateClaimCommandHandler(db,user).Handle(new(first.Id,body),default));var outsider=TestScaffold.AgencyStaff(Guid.NewGuid());await Assert.ThrowsAsync<Kalypsis.Application.Common.AppException>(()=>new UpdateClaimCommandHandler(db,outsider).Handle(new(first.Id,body),default));}
 [Fact] public async Task Every_desktop_party_field_roundtrips_through_existing_claim_endpoints(){var user=TestScaffold.AgencyStaff(Guid.NewGuid());await using var db=TestScaffold.NewDb(user,TestScaffold.Clock);var claim=await Seed(db,user.TenantId!.Value,"CL1");var body=new ClaimInvolvedPartyBody("OtherDriver","QA","2101234567","qa@example.com","012345678","ABC1234","Insurer","P1","Notes","ID1","Athens",100,true,true);var created=await new CreateInvolvedPartyHandler(db,user).Handle(new(claim.Id,body),default);Assert.Equal("ID1",created.IdNumber);Assert.True(created.AtFault);var saved=await new UpdateInvolvedPartyHandler(db,user).Handle(new(created.Id,body with{Address="Patra",ClaimedAmount=200}),default);Assert.Equal("Patra",saved.Address);Assert.Equal(200,saved.ClaimedAmount);var list=await new ListInvolvedPartiesByCustomerHandler(db,user).Handle(new(claim.Policy.CustomerId),default);Assert.Equal("ID1",Assert.Single(list).IdNumber);}
}
